import {NextResponse} from 'next/server';import {db} from '@/lib/db';import {currentUser} from '@/lib/auth';
export async function GET(){if(!await currentUser())return NextResponse.json({error:'Unauthorized'},{status:401});return NextResponse.json(await db.vendor.findMany({orderBy:{vendorName:'asc'}}));}
export async function POST(req:Request){const u=await currentUser();if(!u)return NextResponse.json({error:'Unauthorized'},{status:401});if(u.role==='VIEWER')return NextResponse.json({error:'Read-only access'},{status:403});const {vendorName,defaultCreditPeriod}=await req.json();if(!vendorName?.trim())return NextResponse.json({error:'Vendor name is required'},{status:400});const n=await db.vendor.count();const vendor=await db.vendor.create({data:{vendorName:vendorName.trim(),vendorCode:`VEN-${String(n+1).padStart(5,'0')}`,defaultCreditPeriod:Number(defaultCreditPeriod)||30}});return NextResponse.json(vendor);}
